CREATE TABLE IF NOT EXISTS agent_health (server_id varchar(36) PRIMARY KEY, collector_state varchar(16) NOT NULL DEFAULT 'unknown', collector_message varchar(256) NOT NULL DEFAULT '', state_since datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), queue_depth integer NOT NULL DEFAULT 0, rejected_events integer NOT NULL DEFAULT 0, last_poll_at datetime(6), last_event_at datetime(6), updated_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(server_id) REFERENCES servers(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notification_channels (id varchar(36) PRIMARY KEY, name varchar(128) NOT NULL, kind varchar(16) NOT NULL, config_ciphertext text NOT NULL, last_attempt_at datetime(6), enabled boolean NOT NULL DEFAULT true, created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS alert_rules (id varchar(36) PRIMARY KEY, name varchar(128) NOT NULL, kind varchar(32) NOT NULL, enabled boolean NOT NULL DEFAULT true, threshold_count integer NOT NULL DEFAULT 5, window_seconds integer NOT NULL DEFAULT 300, cooldown_seconds integer NOT NULL DEFAULT 300, server_group varchar(64) NOT NULL DEFAULT '', trusted_cidrs text NOT NULL, channel_ids text NOT NULL, created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS alerts (id varchar(36) PRIMARY KEY, rule_id varchar(36), server_id varchar(36), event_id varchar(36), severity varchar(16) NOT NULL, title varchar(256) NOT NULL, message text NOT NULL, acknowledged_by varchar(36), acknowledged_at datetime(6), resolved_at datetime(6), created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(server_id) REFERENCES servers(id), FOREIGN KEY(acknowledged_by) REFERENCES users(id), INDEX alerts_time(created_at), INDEX alerts_server(server_id,created_at)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS alert_state (state_key varchar(64) PRIMARY KEY, last_alert_at datetime(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notification_jobs (id varchar(36) PRIMARY KEY, alert_id varchar(36) NOT NULL, channel_id varchar(36) NOT NULL, status varchar(16) NOT NULL DEFAULT 'pending', priority integer NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, next_attempt_at datetime(6) NOT NULL, locked_until datetime(6), lease_token varchar(64) NOT NULL DEFAULT '', last_error varchar(512) NOT NULL DEFAULT '', sent_at datetime(6), created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(alert_id) REFERENCES alerts(id), FOREIGN KEY(channel_id) REFERENCES notification_channels(id), INDEX jobs_due(status,next_attempt_at), INDEX jobs_alert(alert_id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO alert_rules(id,name,kind,threshold_count,window_seconds,cooldown_seconds,trusted_cidrs,channel_ids) SELECT '00000000-0000-4000-8000-000000000001','SSH 登录成功','login',1,300,60,'[]','[]' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM alert_rules WHERE id='00000000-0000-4000-8000-000000000001');
